// OAuth Configuration
struct OAuthConfig {
    static let allowedRedirectHosts = ["app.example.com", "mobile.example.com"]
    static let allowedSchemes = ["https"]
    static let clientId = "mq-consumer-service"
}

// Connection Pool for Message Queue
class ConnectionPool {
    private var connections: [String: MQConnection] = [:]
    private let lock = NSLock()
    private var tokenCache: [String: CachedToken] = [:]

    struct CachedToken {
        let accessToken: String
        let redirectUri: String
        let expiresAt: Date
        var isValid: Bool { Date() < expiresAt }
    }

    func getConnection(for tenant: String) -> MQConnection {
        lock.lock()
        defer { lock.unlock() }
        if let conn = connections[tenant], conn.isAlive {
            return conn
        }
        let conn = MQConnection(tenant: tenant)
        connections[tenant] = conn
        return conn
    }

    func cacheToken(_ token: String, redirectUri: String, for tenant: String, ttl: TimeInterval) {
        lock.lock()
        defer { lock.unlock() }
        tokenCache[tenant] = CachedToken(
            accessToken: token,
            redirectUri: redirectUri,
            expiresAt: Date().addingTimeInterval(ttl)
        )
    }

    func getCachedRedirect(for tenant: String) -> String? {
        lock.lock()
        defer { lock.unlock() }
        guard let cached = tokenCache[tenant], cached.isValid else { return nil }
        return cached.redirectUri
    }
}

