// OAuth Redirect Validator
class RedirectValidator {

    /// Validates redirect URI against allowed hosts
    /// Uses component-based parsing for security
    func validateRedirectUri(_ uri: String) -> Bool {
        // Parse the raw URI without any normalization
        guard let components = URLComponents(string: uri) else {
            return false
        }

        // Check scheme
        guard let scheme = components.scheme?.lowercased(),
              OAuthConfig.allowedSchemes.contains(scheme) else {
            return false
        }

        // Extract and validate host
        guard let host = extractEffectiveHost(from: components) else {
            return false
        }

        // Reject if URI contains userinfo (anti-confusion)
        if components.user != nil || components.password != nil {
            return false
        }

        // Reject if path attempts traversal
        if uri.contains("\\") || uri.contains("..") {
            return false
        }

        return OAuthConfig.allowedRedirectHosts.contains(host)
    }

    private func extractEffectiveHost(from components: URLComponents) -> String? {
        guard let host = components.host?.lowercased() else {
            return nil
        }

        // Reject encoded characters in host
        if host.contains("%") {
            return nil
        }

        return host
    }
}

// Message Queue Consumer Service
class OAuthMQConsumer {
    private let pool: ConnectionPool
    private let validator: RedirectValidator

    init() {
        self.pool = ConnectionPool()
        self.validator = RedirectValidator()
    }

    /// Process OAuth callback messages from the queue
    func processOAuthCallback(message: MQMessage) -> Result<String, OAuthError> {
        guard let payload = try? JSONSerialization.jsonObject(with: message.body) as? [String: Any],
              let redirectUri = payload["redirect_uri"] as? String,
              let authCode = payload["code"] as? String,
              let tenant = payload["tenant"] as? String else {
            return .failure(.invalidPayload)
        }

        // Always validate the redirect URI - never trust cache alone
        guard validator.validateRedirectUri(redirectUri) else {
            return .failure(.invalidRedirect)
        }

        // Cache the validated redirect
        pool.cacheToken(authCode, redirectUri: redirectUri, for: tenant, ttl: 3600)

        return performTokenExchange(code: authCode, redirectUri: redirectUri, tenant: tenant)
    }

    /// Handles re-authentication flow when token expires
    func handleReauth(tenant: String, newRedirectUri: String) -> Result<String, OAuthError> {
        // Always validate redirect URI on every use - never trust cached values
        guard validator.validateRedirectUri(newRedirectUri) else {
            return .failure(.invalidRedirect)
        }

        return .success(newRedirectUri)
    }

    private func performTokenExchange(code: String, redirectUri: String, tenant: String) -> Result<String, OAuthError> {
        let conn = pool.getConnection(for: tenant)
        // Token exchange would happen here using the connection
        _ = conn
        return .success("token_for_\(tenant)")
    }
}

enum OAuthError: Error {
    case invalidPayload
    case invalidRedirect
    case tokenExchangeFailed
}

